import{_ as a,a0 as r,w as i,s as d,ao as l,I as u,x as t,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux有问必答——如何为sudo命令定义PATH环境变量 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答——如何为sudo命令定义PATH环境变量 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答——如何为sudo命令定义PATH环境变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答——如何为sudo命令定义PATH环境变量 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands","title":"Linux有问必答——如何为sudo命令定义PATH环境变量","tag":"201409","desc":""},"relativePath":"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands.md","filePath":"[post].md"}'),m={name:"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands.md"};function p(T,o,f,A,x,_){const n=r("Link");return i(),d("div",null,[o[11]||(o[11]=l(`<h1 id="linux有问必答——如何为sudo命令定义path环境变量" tabindex="-1">Linux有问必答——如何为sudo命令定义PATH环境变量 <a class="header-anchor" href="#linux有问必答——如何为sudo命令定义path环境变量" aria-label="Permalink to “Linux有问必答——如何为sudo命令定义PATH环境变量”">​</a></h1><blockquote><p><strong>问题</strong>:我安装了一个程序到/usr/local/bin目录下，这个程序需要root权限才能执行，当我用sudo去执行它时，收到&quot;sudo: XXXXX: command not found&quot;的错误提示，不知道为什么/usr/local/bin没有被包含到PATH环境变量下面来，我该如何解决这个问题？</p></blockquote><p>当你使用sudo去执行一个程序时，处于安全的考虑，这个程序将在一个新的、最小化的环境中执行，也就是说，诸如PATH这样的环境变量，在sudo命令下已经被重置成默认状态了。所以当一个刚初始化的PATH变量中不包含你所要运行的程序所在的目录，用sudo去执行，你就会得到&quot;command not found&quot;的错误提示。</p><p>要想改变PATH在sudo会话中的初始值，用文本编辑器打开/etc/sudoers文件，找到&quot;secure_path&quot;一行，当你执行sudo 命令时，&quot;secure_path&quot;中包含的路径将被当做默认PATH变量使用。</p><p>添加所需要的路径(如 /usr/local/bin）到&quot;secure_path&quot;下，在开篇所遇见的问题就将迎刃而解。</p><pre><code>Defaults    secure_path = /sbin:/bin:/usr/sbin:/usr/bin:/usr/local/bin
</code></pre><p>这个修改会即刻生效。</p><hr>`,8)),u("p",null,[o[1]||(o[1]=t("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/define-path-environment-variable-sudo-commands.html"},{default:s(()=>[...o[0]||(o[0]=[t("http://ask.xmodulo.com/define-path-environment-variable-sudo-commands.html",-1)])]),_:1})]),u("p",null,[o[4]||(o[4]=t("译者：",-1)),e(n,{href:"https://github.com/nd0104"},{default:s(()=>[...o[2]||(o[2]=[t("nd0104",-1)])]),_:1}),o[5]||(o[5]=t(" 校对：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...o[3]||(o[3]=[t("Caroline",-1)])]),_:1})]),u("p",null,[o[8]||(o[8]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[6]||(o[6]=[t("LCTT",-1)])]),_:1}),o[9]||(o[9]=t(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...o[7]||(o[7]=[t("Linux中国",-1)])]),_:1}),o[10]||(o[10]=t(" 荣誉推出",-1))])])}const H=a(m,[["render",p]]);export{L as __pageData,H as default};
